  { auto _e = NAME(); if (_e) _o->NAME = _e->str(); }
  { auto _e = TYPE(); if (_e) _o->TYPE = _e->str(); }
  { auto _e = UNIT(); if (_e) _o->UNIT = _e->str(); }
  { auto _e = SORTABLE(); _o->SORTABLE = _e; }
  { auto _e = INDEXED(); _o->INDEXED = _e; }
