inline ::flatbuffers::Offset<QRP> CreateQRP(::flatbuffers::FlatBufferBuilder &_fbb, const QRPT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return QRP::Pack(_fbb, _o, _rehasher);
}

